/** Побочный импорт стилей внутри общего пакета: `import "./settingsShell.css"`.
 *
 *  Зачем объявление. У apps/desktop типы CSS приходят из "vite/client", но
 *  общий пакет НАМЕРЕННО собран без него (см. комментарий в tsconfig.json:
 *  пакет едят оба бандлера, и Vite-only идиомы в Next ломаются молча). Без
 *  этой строки tsc падает на любом импорте стилей — а компонент, который
 *  носит свой вид с собой, лучше компонента, чей вид надо не забыть подключить
 *  на каждой площадке отдельно.
 *
 *  Оба сборщика такой импорт понимают: Vite кладёт стили в бандл сам, Next —
 *  потому что @muza/app перечислен в transpilePackages (apps/web/next.config.ts),
 *  а в package.json пакета стоит "sideEffects": ["*.css"] — стили не выкинет
 *  tree-shaking. */
declare module "*.css";
